// Function to convert Google Drive URL to shareable view URL
const getDirectImageUrl = (driveUrl) => {
  if (
    !driveUrl ||
    driveUrl === "No photo" ||
    driveUrl === "Error storing photo"
  ) {
    return null;
  }

  // If it's already a shareable view URL, return as is
  if (driveUrl.includes("/file/d/") && driveUrl.includes("/view")) {
    return driveUrl;
  }

  // Convert Google Drive file URL to shareable view URL
  if (driveUrl.includes("drive.google.com/file/d/")) {
    const fileId = driveUrl.match(/\/file\/d\/([^\/]+)/)?.[1];
    if (fileId) {
      return `https://drive.google.com/file/d/${fileId}/view?usp=drive_link`;
    }
  }

  // If it's a direct download URL, convert to shareable view URL
  if (driveUrl.includes("uc?id=") || driveUrl.includes("export=download")) {
    const fileId = driveUrl.match(/[?&]id=([^&]+)/)?.[1];
    if (fileId) {
      return `https://drive.google.com/file/d/${fileId}/view?usp=drive_link`;
    }
  }

  // If it's just a file ID, create shareable URL
  if (driveUrl.match(/^[a-zA-Z0-9_-]{20,}$/)) {
    return `https://drive.google.com/file/d/${driveUrl}/view?usp=drive_link`;
  }

  return driveUrl;
};

