                    sx={{ color: "rgba(255,255,255,0.5)" }}
                  >
                    PNG, JPG, JPEG (Max 5MB each)
                  </Typography>
                </Box>
              )}
              <Grid container spacing={2}>
                {addPhotosPreview.map((preview, idx) => (
                  <Grid item key={idx}>
                    <Box
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                      }}
                    >
                      <Avatar
                        src={preview}
                        sx={{
                          width: 60,
                          height: 60,
                          border: "2px solid #FF9800",
                          marginBottom: 1,
                        }}
                      />
                      <Chip
                        label={addPhotos[idx]?.name || ""}
                        variant="outlined"
                        sx={{
                          color: "white",
                          borderColor: "rgba(255,255,255,0.3)",
                          marginBottom: 1,
                        }}
                      />
                      <IconButton
                        sx={{ color: "#FF9800" }}
                        onClick={() => handleRemoveAddPhoto(idx)}
                      >
                        <Delete />
                      </IconButton>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Box>

            {/* Rating */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Rating *
              </Typography>
              <Rating
                value={reviewData.rating}
                onChange={(e, newValue) =>
                  handleInputChange("rating", newValue)
                }
                size="large"
                sx={{
                  color: "#FF9800",
                  "& .MuiRating-iconEmpty": {
                    color: "white", // White color for unselected stars
                  },
                  "& .MuiRating-iconFilled": {
                    color: "#FF9800",
                  },
                }}
              />
            </Box>

            {/* Comment - Now Mandatory */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Review *
              </Typography>
              <TextField
                multiline
                rows={4}
                fullWidth
                value={reviewData.comment}
                onChange={(e) => handleInputChange("comment", e.target.value)}
                placeholder="Share your experience with BT's TT Academy... (Required)"
                variant="outlined"
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": { borderColor: "rgba(255,255,255,0.2)" },
                    "&:hover fieldset": {
                      borderColor: "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": { borderColor: "#FF9800" },
                  },
                }}
              />
            </Box>
          </Box>
        </DialogContent>
        <DialogActions
          sx={{ padding: 3, borderTop: "1px solid rgba(255,255,255,0.1)" }}
        >
          <Button
            onClick={handleReviewDialogClose}
            disabled={loading}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover:not(:disabled)": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleReviewSubmit}
            variant="contained"
            disabled={
  !reviewData.name.trim() ||
  reviewData.rating === 0 ||
  loading ||
  hasReviewed ||
  !reviewData.comment.trim()
}
            sx={{
              background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
              "&:hover:not(:disabled)": {
                background: "linear-gradient(45deg, #E65100 30%, #BF360C 90%)",
              },
              "&:disabled": {
                background: "rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.3)",
              },
              minWidth: "120px",
            }}
          >
            {loading ? (
              <CircularProgress size={24} sx={{ color: "white" }} />
            ) : (
              "Submit Review"
            )}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Feedback Dialog */}
      <Dialog
        open={feedbackDialog.open}
        onClose={handleFeedbackDialogClose}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
            textAlign: "center",
            padding: 2,
          },
        }}
      >
        <DialogTitle>
          <Typography
            variant="h6"
            sx={{
              color:
                feedbackDialog.severity === "error"
                  ? "#FF5252"
                  : feedbackDialog.severity === "success"
                  ? "#4CAF50"
                  : feedbackDialog.severity === "info"
                  ? "#FF9800"
                  : "#FFC107",
              mb: 1,
            }}
          >
            {feedbackDialog.severity.charAt(0).toUpperCase() +
              feedbackDialog.severity.slice(1)}
          </Typography>
        </DialogTitle>
        <DialogContent>
          <Typography variant="body1">{feedbackDialog.message}</Typography>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleFeedbackDialogClose}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default NavBar;
